package santa

import io.circe.Json
import io.circe.parser.{parse => parseJson}

import santa.runner.Runner

/** Guard for `Runner.evalEntry("santa-eval/v6-fullctx", ...)` — the Rudolph arm that
  * routes v6-fullctx vectors to `WalkerOracle.evalEnvelope` (full reconstructed context).
  *
  * Fixture: the REAL h2571 golden
  * (ergots/tools/mainnet-validate/captured/h2571-3d8b8635ca52.json).
  * Expected: SigmaProp d3 @ cost 938. Version: activated 3, ergoTree 3 (v6 chain, mainnet). */
class EvalFullCtxRunnerTest extends munit.FunSuite {

  // The h2571 golden — tree_bytes_hex and context.* VERBATIM from the captured file.
  // `version` is supplied here (goldens omit it; v6 mainnet ⇒ activated 3 / ergoTree 3).
  private val entryJson: Json = parseJson("""{
    "name": "h2571-tx70c3473a-input0#0",
    "schema": "santa-eval/v6-fullctx",
    "version": {"activated": 3, "ergoTree": 3},
    "tree_bytes_hex": "1b82010304000e208437796cc1821f8e89272a5d24a0055a80a5eef6ba4e172bca5e905e11e1bf7205d005d802d601b2a5730000d602c1a7d1eded93cbc2720173019683050193c17201720293e4c672010464e4c6a7046493e4c672010504e4c6a7050493e4c672010606e4c6a7060693e4c6720107057202927ea3059ae4c6a707057302",
    "context": {
      "self_index": 0,
      "inputs": [
        "",
        "808095e789c6040008cd0281dcc97683d140b4538cb99c0ed168ed01667b6e0d6d1f505d4ee9ec5198bc8de60d00004ade23d69e7f1248f751825cf13d84e48e0db18eec0b307db8d71459b2841e2a00"
      ],
      "data_inputs": [],
      "outputs": [
        "",
        "c0843d1005040004000e36100204a00b08cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798ea02d192a39a8cc7a701730073011001020402d19683030193a38cc7b2a57300000193c2b2a57301007473027303830108cdeeac93b1a573048914000070c3473a32853507053bf22063dd8129e951e1ba5b91f543fa626da774bab72e01",
        "c0fbd7e689c6040008cd02856c5e4eb4b915005dccb8e0f42bed1777cae48565be13a77cbf31e3c93f45158914000070c3473a32853507053bf22063dd8129e951e1ba5b91f543fa626da774bab72e02"
      ],
      "headers": [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
      ],
      "pre_header_hex": "043578d8f49d45cec1848643b8d50e82c20722918ff315e162b5f2cd9191b21866b4dc938aa93383b282288b140352c9d64b4da9c099490fb76ac569177d4b917a87480b06aa535d78b979995669000000",
      "height": 2571,
      "extension": {},
      "input_extensions": [
        {},
        {}
      ]
    }
  }""").fold(e => sys.error(s"bad fixture JSON: $e"), identity)

  test("Runner.evalEntry dispatches santa-eval/v6-fullctx to evalFullContext (h2571 golden)") {
    val (name, actual) = Runner.evalEntry("santa-eval/v6-fullctx", entryJson)
    assertEquals(name, "h2571-tx70c3473a-input0#0")
    val c = actual.hcursor
    assertEquals(c.downField("error").focus, Some(Json.Null), s"error must be null; got: ${actual.noSpaces}")
    assertEquals(c.downField("value").get[String]("kind").toOption, Some("SigmaProp"))
    assertEquals(c.downField("value").get[String]("raw_hex").toOption, Some("d3"))
    assertEquals(c.get[Long]("cost").toOption, Some(938L))
  }
}
